<?php
namespace App\Models;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;
final class Quote extends Model{use HasUuids;protected$fillable=['tenant_id','party_id','risk_asset_id','attribution_id','line_code','status','currency','risk_facts','expires_at','version','channel','submitted_at','rated_at','comparison_context','lifecycle_state','quote_number','partner_id','question_set_id','generated_at','sent_at','viewed_at','accepted_at','declined_at','decline_reason_code','expired_at','cancelled_at'];protected$appends=['is_expired'];protected function casts():array{return['risk_facts'=>'array','expires_at'=>'datetime','submitted_at'=>'datetime','rated_at'=>'datetime','comparison_context'=>'array','generated_at'=>'datetime','sent_at'=>'datetime','viewed_at'=>'datetime','accepted_at'=>'datetime','declined_at'=>'datetime','expired_at'=>'datetime','cancelled_at'=>'datetime'];}public function getIsExpiredAttribute():bool{return(bool)($this->expires_at&&$this->expires_at->isPast());}public function party():BelongsTo{return$this->belongsTo(Party::class);}public function tenant():BelongsTo{return$this->belongsTo(Tenant::class);}public function riskAsset():BelongsTo{return$this->belongsTo(RiskAsset::class);}public function offers():HasMany{return$this->hasMany(QuoteOffer::class);}public function risks():HasMany{return$this->hasMany(\App\Application\Quotes\Models\QuoteRisk::class)->orderBy('sequence');}}
